```css
/* 摘要行 hover：只过渡颜色 */
.group\/activity-header { transition: color .15s cubic-bezier(0,0,.2,1); }

/* 展开：height + opacity，.15s ease-out，JS 驱动 height */
.detail-collapsible { overflow: hidden; height: 0; opacity: 0;
  transition: height .15s cubic-bezier(0,0,.2,1), opacity .15s cubic-bezier(0,0,.2,1); }

/* chevron 旋转 */
[data-chevron] { transition: transform .15s cubic-bezier(0,0,.2,1); }
[aria-expanded="true"] > [data-chevron] { transform: rotate(90deg); }

/* 复制按钮：hover 才出现 */
.copy-btn { opacity: 0; transition: opacity .15s ease; }
.group\/command:hover .copy-btn { opacity: 1; }
```

