    submit(`/api/quests/${encodeURIComponent(quest.id)}/grants${revoke ? "/revoke" : ""}`,
      { scope: target, expected_plan_revision: revision });
  };
  return <section className="grant-section"><div className="section-heading"><span>工作区权限</span></div>
