an>{text((visiblePanel.value[1] as Row)?.cost_limit_microunits)}</span></SettingsRow><SettingsRow label="货币"><span>{text((visiblePanel.value[1] as Row)?.currency)}</span></SettingsRow></div>{rows((visiblePanel.value[1] as Row)?.recent_unsettled).length > 0 && <><div className="section-heading spaced"><span>未结算请求</span></div>{rows((visiblePanel.value[1] as Row)?.recent_unsettled).map((attempt, index) => <div className="plan-node" key={String(index)}><strong>{text(attempt.code)} · {text(attempt.purpose)}</strong><small>输入预留 {text(attempt.input_reserved)} · 输出预留 {text(attempt.output_reserved)}</small><small>隔离至：{timeText(attempt.recover_after)}</small></div>)}</>}<TechnicalDetails value={visiblePanel.value} /></>}{restoreFenced === true && <div className="restore-warning"><strong>恢复待复核，后台与写入已暂停</strong><p>{restoreStatus?.review_available === true ? "请先核对当前工作区与回滚目录，退出应用后按 README 的离线维护步骤提交复核；此界面不会自动解除锁定。" : "复核记录不可用或损坏，请人工检查；不要尝试自动解锁。"}</p><div className="settings-facts"><SettingsRow label="清单摘要"><span className="break">{text(restoreStatus?.manifest_sha256)}</span></SettingsRow><SettingsRow label="回滚目录"><span className="break">{text(restoreStatus?.rollback_directory)}</span></SettingsRow></div></div>}{native && (setting === "storage" || setting === "general") && <><div className="section-heading spaced"><span>工作空间维护</span></div><p className="notice">备份和恢复会暂时停止 Core；恢复成功后写操作保持锁定，需人工核对。</p><label className="field-label">备份目录的绝对路径<input value={workspacePath} onChange={(event) => setWorkspacePath(event.target.value)} placeholder="例如 D:/Backup/FORGE" /></label><div className="button-row"><button className="button" disabled={writesBlocked || actionBusy || !workspacePath.trim()} onClick={() => void maintainWorkspace("backup")}>备份</button><button className="button" disabled={writesBlocked || actionBusy || !workspacePath.trim()} onClick={() => void maintainWorkspace("restore")}>恢复</button><button className="button" disabled={writesBlocked || actionBusy} onClick={() => void retryRuntime()}>重启 Core</button></div>{workspaceOperation && <p className={workspaceOperation.status === "unknown" || workspaceOperation.result?.ok === false ? "notice error" : "notice"} role="status">{workspaceOperation.status === "running" ? "正在备份或恢复，完成后可退出。" : workspaceOperation.status === "unknown" ? (workspaceOperation.acknowledged ? "未知结果已归档；这不表示操作成功，也不会解除恢复锁定。" : "维护结果未知，请人工核查；不要重复发起。") : workspaceOperation.result?.ok ? (workspaceOperation.operation === "restore" ? "恢复完成；写操作已锁定，请先人工核对。" : "备份完成。") : `维护未完成：${text(workspaceOperation.result?.code)}`}{workspaceOperation.operationId && <> 操作 ID：<code>{workspaceOperation.operationId}</code></>}</p>}{workspaceOperation?.status === "unknown" && !workspaceOperation.acknowledged && workspaceOperation.operationId && <><label className="field-label">人工核查说明<input value={reviewReason} onChange={(event) => setReviewReason(event.target.value)} /></label><button className="button" disabled={actionBusy || !reviewReason.trim() || runtimeStatus?.state !== "ready"} onClick={() => void acknowledgeUnknown()}>归档未知结果</button><p className="notice">仅归档，不表示成功，不解除恢复锁或预算限制。</p></>}</>}{(setting === "general" || setting === "environment") && Array.isArray(visiblePanel.value) && <OperatorSettings key={text((visiblePanel.value[0] as Row)?.revision, "0")} settings={visiblePanel.value[0] as Row} budget={visiblePanel.value[1] as Row} blocked={writesBlocked || actionBusy} save={(value) => void perform("/api/settings", value)} />}{(setting === "general" || setting === "connections") && <><div className="section-heading spaced"><span>供应商凭据</span></div>{native ? <div className="credential-form"><label className="field-label">供应商 ID<input value={providerId} onChange={(event) => setProviderId(event.target.value)} autoComplete="off" /></label><label className="field-label">凭据引用<input value={credentialRef} onChange={(event) => setCredentialRef(event.target.value)} autoComplete="off" /></label><label className="field-label">新凭据<input ref={credentialInput} ty