ton" disabled={writesBlocked || actionBusy} onClick={() => void retryRuntime()}>重启 Core</button></div>{workspaceOperation && <p className={workspaceOperation.status === "unknown" || workspaceOperation.result?.ok === false ? "notice error" : "notice"} role="status">{workspaceOperation.status === "running" ? "正在备份或恢复，完成后可退出。" : workspaceOperation.status === "unknown" ? (workspaceOperation.acknowledged ? "未知结果已归档；这不表示操作成功，也不会解除恢复锁定。" : "维护结果未知，请人工核查；不要重复发起。") : workspaceOperation.result?.ok ? (workspaceOperation.operation === "restore" ? "恢复完成；写操作已锁定，请先人工核对。" : "备份完成。") : `维护未完成：${text(workspaceOperation.result?.code)}`}{workspaceOperation.operationId && <> 操作 ID：<code>{workspaceOperation.operationId}</code></>}</p>}{workspaceOperation?.status === "unknown" && !workspaceOperation.acknowledged && workspaceOperation.operationId && <><label className="field-label">人工核查说明<input value={reviewReason} onChange={(event) => setReviewReason(event.target.value)} /></label><button className="button" disabled={actionBusy || !reviewReason.trim() || runtimeStatus?.state !== "ready"} onClick={() => void acknowledgeUnknown()}>归档未知结果</button><p className="notice">仅归档，不表示成功，不解除恢复锁或预算限制。</p></>}</>}{(setting === "general" || setting === "environment") && Array.isArray(visiblePanel.value) && <OperatorSettings key={text((visiblePanel.value[0] as Row)?.revision, "0")} settings={visiblePanel.value[0] as Row} budget={visiblePanel.value[1] as Row} blocked={writesBlocked || actionBusy} save={(value) => void perform("/api/settings", value)} />}{(setting === "general" || setting === "connections") && <><div className="section-heading spaced"><span>供应商凭据</span></div>{native ? <div className="credential-form"><label className="field-label">供应商 ID<input value={providerId} onChange={(event) => setProviderId(event.target.value)} autoComplete="off" /></label><label className="field-label">凭据引用<input value={credentialRef} onChange={(event) => setCredentialRef(event.target.value)} autoComplete="off" /></label><label className="field-label">新凭据<input ref={credentialInput} type="password" autoComplete="new-password" /></label><div className="button-row"><button className="button primary" disabled={writesBlocked} onClick={() => void credential("set")}>保存</button><button className="button" onClick={() => void credential("exists")}>检查是否存在</button><button className="button" disabled={writesBlocked} onClick={() => void credential("delete")}>删除</button></div>{credentialStatus && <p className="notice" role="status">{credentialStatus}</p>}</div> : <p className="notice">浏览器开发模式不提供系统凭据库。请在桌面应用中管理凭据。</p>}</>}</>}</>}
