export function SettingsRow({ label, description, children }: { label: ReactNode; description?: ReactNode; children: ReactNode }) {
  return <div className="settings-row">
    <div className="settings-row-text"><div className="settings-row-label">{label}</div>{description && <div className="settings-row-desc">{description}</div>}</div>
    <div className="settings-row-control">{children}</div>
  </div>;
}

export default function SettingsView({ selected, onSelect, children }: { selected: SettingId; onSelect: (id: SettingId) => void; children: ReactNode }) {
  const [query, setQuery] = useState("");
  const search = query.trim().toLocaleLowerCase();
  const groups = settingGroups.map((group) => ({ ...group, items: group.items.filter((item) => `${group.label} ${item.label} ${item.accessibleLabel || ""}`.toLocaleLowerCase().includes(search)) })).filter((group) => group.items.length > 0);
  const current = settingGroups.flatMap((group) => group.items).find((item) => item.id === selected)!;
  return <section className="settings-view" aria-label="设置">
    <nav className="settings-nav" aria-label="设置导航">
      <div className="settings-search"><input type="search" aria-label="搜索设置" placeholder="搜索设置" value={query} onChange={(event) => setQuery(event.target.value)} /></div>
      {groups.map((group) => <div className="settings-nav-section" key={group.label}>
        <h2 className="settings-nav-group">{group.label}</h2>
        {group.items.map((item) => <button type="button" key={item.id} className={`settings-nav-item${selected === item.id ? " active" : ""}`} aria-label={item.accessibleLabel} aria-current={selected === item.id ? "page" : undefined} onClick={() => onSelect(item.id)}><SettingIcon id={item.id} /><span>{item.label}</span></button>)}
      </div>)}
      {!groups.length && <p className="notice">未找到匹配的设置</p>}
    </nav>
    <div className="settings-content"><h1 className="settings-title">{current.label}</h1>{children}</div>
  </section>;
}

