.code-toolbar button {
  border:0;
  background:none;
  color:var(--color-text-accent);
  font-size:11px}
.code-block pre {
  margin:0;
  padding:12px;
  max-height:420px;
  overflow:auto;
  background:transparent;
  color:var(--color-text);
  font-size:12.5px;
  line-height:1.6;
}
.code-block code {
  background:none;
  padding:0}
.copy-status,.image-placeholder {
  display:inline-block;
  color:var(--app-color-text-foreground-tertiary);
  font-size:11px}
.event-group {
  max-width:var(--thread-content-max-width);
  margin:0 auto 20px;
  padding-left:0;
  color:var(--app-color-text-foreground-tertiary)}
.event-line {
  margin:0}
.event-group > summary, .event-line > summary, .earlier-events > summary {
  display:inline-flex;
  align-items:center;
  align-self:flex-start;
  max-width:100%;
  height:21px;
  min-width:0;
  padding:0;
  gap:4px;
  cursor:pointer;
  font-size:14px;
  line-height:21px;
  font-weight:400;
  color:var(--app-color-text-foreground-tertiary);
  list-style:none;
  border:0;
  border-radius:0;
  background:none;
  text-align:start}
.event-group > summary:hover, .event-line > summary:hover, .earlier-events > summary:hover {
  color:var(--color-text)}
.event-group > summary::-webkit-details-marker, .event-line > summary::-webkit-details-marker, .earlier-events > summary::-webkit-details-marker {
  display:none}
.event-group > summary > span, .event-line > summary > span {
  min-width:0;
  overflow:hidden;
  text-overflow:ellipsis;
  white-space:nowrap}
.event-group > summary svg, .event-line > summary svg {
  width:16px;
  height:16px;
  flex:none;
  margin:0}
.event-target {
  color:inherit}
.event-mode {
  font-size:12px;
  color:inherit}
.event-failed,.event-line.failed {
  color:var(--color-status-error)}
.event-line.unknown {
  color:var(--color-status-warning)}
.event-detail {
