  color:var(--app-color-text-foreground-tertiary)}
.earlier-events>summary {
  margin:0;
  color:var(--app-color-text-foreground-tertiary)}
.command-card {
  display:flex;
  flex-direction:column;
  min-width:0;
  overflow:hidden;
  border:0.8px solid var(--color-border-strong);
  border-radius:var(--radius-lg);
  background:var(--color-background-command)}
.command-card > header {
  padding:4px 8px;
  font-size:13px;
  line-height:18px;
  color:var(--muted)}
.command-card .command-line { position:relative; min-width:0; }
.command-card .cmd {
  margin:0;
  padding:8px 32px 0 8px;
  font-family:var(--font-mono);
  font-size:13px;
  line-height:20px;
  font-weight:400;
  color:var(--color-text-secondary);
  white-space:pre-wrap;
  word-break:break-word;
  display:-webkit-box;
  -webkit-line-clamp:2;
  -webkit-box-orient:vertical;
