.command-card .cmd::before { content:"$"; margin-inline-end:1ch; color:var(--muted); }
.command-card .cmd code, .command-card .out code { font:inherit; color:inherit; background:none; padding:0; }
.command-card .out {
  display:flex;
  flex-direction:column-reverse;
