  font-size:13px;
  line-height:20px;
  font-weight:500;
  white-space:pre;
  overflow-wrap:normal;
  color:var(--color-text-secondary);
  background:none}
.copy-btn { opacity:0; }
.command-card:hover .copy-btn, .command-card:focus-within .copy-btn, .copy-btn:focus-visible { opacity:1; }
.command-card .copy-btn { position:absolute; right:4px; top:4px; display:grid; place-items:center; width:24px; height:24px; padding:0; border:0; border-radius:var(--radius-md); background:none; color:var(--muted); }
.command-card .copy-btn:hover { color:var(--color-text); background:var(--color-background-secondary-ghost-hover); }
.resource-card { display:flex; align-items:center; gap:12px; min-width:0; padding:12px; border:1px solid var(--color-border-subtle); border-radius:var(--radius-lg); background:var(--app-color-background-surface-under); }
.resource-icon { display:grid; place-items:center; flex:none; width:40px; height:40px; border-radius:var(--radius-lg); background:var(--color-background-secondary-ghost-hover); }
.resource-icon svg { width:24px; height:24px; }
.resource-card > div { min-width:0; }
.resource-card strong { display:block; font-size:14px; line-height:21px; font-weight:500; color:var(--color-text); overflow-wrap:anywhere; }
.resource-card small { font-size:13px; line-height:18px; }
.approval-card { flex-direction:column; align-items:stretch; gap:8px; }
