.approval-card .button-row { margin-top:0; }

@media (hover:none) {
  .message .message-meta, .copy-btn { opacity:1; }
}
.outgoing-error {
  color:var(--color-status-error);
  font-size:11px;
  margin-top:8px;
  overflow-wrap:anywhere}
.outgoing-error button {
  margin-left:8px}

.restore-warning {
  margin:18px 0;
  padding:12px;
  border:1px solid var(--color-border-warning);
  border-radius:8px;
  background:var(--color-background-warning);
